export type Cell = [number, number];

const key = ([x, y]: Cell): string => `${x},${y}`;

const neighbors = ([x, y]: Cell): Cell[] => [
  [x - 1, y - 1],
  [x, y - 1],
  [x + 1, y - 1],
  [x - 1, y],
  [x + 1, y],
  [x - 1, y + 1],
  [x, y + 1],
  [x + 1, y + 1],
];

export const nextGeneration = (liveCells: Cell[]): Cell[] => {
  const living = new Set(liveCells.map(key));
  const liveNeighborCount = (cell: Cell): number =>
    neighbors(cell).filter((neighbor) => living.has(key(neighbor))).length;

  const candidates = new Map<string, Cell>();
  for (const cell of liveCells) {
    candidates.set(key(cell), cell);
    for (const neighbor of neighbors(cell)) {
      candidates.set(key(neighbor), neighbor);
    }
  }

  return [...candidates.values()].filter((cell) => {
    const count = liveNeighborCount(cell);
    return living.has(key(cell)) ? count === 2 || count === 3 : count === 3;
  });
};

